<template><view class="page"><view class="head"><text>第 {{ question.questionNo || currentNo || 1 }} 题 / 5</text><text>{{ remaining }} 秒</text><text class="rule" @click="openRules">?</text></view><image v-if="question.questionImageUrl" class="picture" :src="imageUrl(question.questionImageUrl)" mode="aspectFill"/><text class="prompt">猜猜以上内容是下面哪个职业的工作场景？</text><view v-for="(label,key) in options" :key="key" class="option" :class="{disabled: submitting}" @click="answer(key)"><text>{{ key }}. {{ label }}</text></view><view v-if="rulesVisible" class="mask"><view class="modal"><text class="modal-title">游戏规则</text><text class="modal-body">每题限时 60 秒，选择一个答案。完成五题后继续探索职业世界。</text><button type="primary" @click="closeRules">我知道了</button></view></view></view></template>
<script>
import { getRecord, submitAnswer, userMessage } from '@/api/zycck'
import config from '@/config/api.js'
export default { data: () => ({ instanceId:'', gameId:'', recordId:'', question:{}, currentNo:1, remaining:60, timer:null, rulesVisible:false, rulesClosed:false, submitting:false }), onLoad(o){ Object.assign(this,{instanceId:o.instanceId||'',gameId:o.gameId||'',recordId:o.recordId||''}); this.rulesVisible = o.skipRules !== '1'; this.load() }, onUnload(){ this.stopTimer() }, computed:{ options(){ const q=this.question||{}; return { A:q.optionA||q.options&&q.options.A||'', B:q.optionB||q.options&&q.options.B||'', C:q.optionC||q.options&&q.options.C||'', D:q.optionD||q.options&&q.options.D||'' } } }, methods:{ imageUrl(v){ return v&&(/^\/(profile|upload)\//.test(v)?config.BASE_URL+v:v) }, async load(){ if(!this.recordId)return; try{ const r=await getRecord(this.recordId); const d=r.data||{}; this.question=d.question||d.currentQuestion||{}; this.currentNo=d.currentQuestionNo||this.question.questionNo||1; this.remaining=Number(d.remainingSeconds==null?60:d.remainingSeconds); if(this.currentNo > 1) this.rulesVisible = false; if(d.finished||d.status==='finished') return uni.redirectTo({url:`/pages/zycck/exploration-list?recordId=${this.recordId}&instanceId=${this.instanceId}&gameId=${this.gameId}&readOnly=1`}); if(!this.rulesVisible) this.startTimer() }catch(e){uni.showToast({title:userMessage(e,'游戏进度加载失败，请重试'),icon:'none'})} }, openRules(){ this.stopTimer(); this.rulesVisible=true }, closeRules(){ this.rulesVisible=false; this.rulesClosed=true; this.startTimer() }, startTimer(){this.stopTimer(); if(this.rulesVisible)return; if(this.remaining<=0)return this.timeout(); this.timer=setInterval(()=>{if(this.rulesVisible)return; this.remaining--; if(this.remaining<=0)this.timeout()},1000)}, stopTimer(){if(this.timer){clearInterval(this.timer);this.timer=null}}, async timeout(){this.stopTimer(); if(this.submitting)return; this.submitting=true; try{const r=await submitAnswer(this.recordId,{questionId:this.question.questionId,questionNo:this.currentNo,timeoutFlag:true}); this.advance(r.data||{})}catch(e){uni.showToast({title:userMessage(e,'答题超时，正在进入下一题'),icon:'none'});this.load()}finally{this.submitting=false}}, async answer(key){if(this.submitting||this.rulesVisible)return; this.submitting=true; this.stopTimer(); try{const r=await submitAnswer(this.recordId,{questionId:this.question.questionId,questionNo:this.currentNo,optionKey:key,timeoutFlag:false}); const d=r.data||{}; if(d.feedback||d.correctCareer){uni.redirectTo({url:`/pages/zycck/feedback?recordId=${this.recordId}&instanceId=${this.instanceId}&gameId=${this.gameId}&skipRules=1&payload=${encodeURIComponent(JSON.stringify(d))}`})}else this.advance(d)}catch(e){uni.showToast({title:userMessage(e,'答案提交失败，请重试'),icon:'none'});this.startTimer()}finally{this.submitting=false}}, advance(d){if(d.nextQuestion||d.question){this.question=d.nextQuestion||d.question;this.currentNo=d.currentQuestionNo||this.currentNo+1;this.remaining=Number(d.remainingSeconds==null?60:d.remainingSeconds);this.startTimer()}else if(d.stage==='summary'||d.finishedFive){uni.redirectTo({url:`/pages/zycck/summary?recordId=${this.recordId}&instanceId=${this.instanceId}&gameId=${this.gameId}`})}else this.load()} } }
</script>
<style scoped>.page{min-height:100vh;padding:28rpx;background:#f5f7fb}.head{display:flex;justify-content:space-between;align-items:center;color:#334155;font-size:28rpx}.rule{width:52rpx;height:52rpx;line-height:52rpx;text-align:center;border-radius:50%;background:#1b76fe;color:#fff;font-weight:700}.picture{width:100%;height:380rpx;margin:36rpx 0;border-radius:18rpx}.prompt{display:block;font-size:32rpx;color:#1f2937;margin-bottom:26rpx}.option{padding:28rpx;margin:18rpx 0;background:#fff;border-radius:14rpx;color:#243b53}.disabled{opacity:.6}.mask{position:fixed;inset:0;background:rgba(0,0,0,.5);display:flex;align-items:center;justify-content:center}.modal{width:640rpx;padding:44rpx;background:#fff;border-radius:20rpx}.modal-title{display:block;font-size:38rpx;font-weight:700;text-align:center}.modal-body{display:block;margin:34rpx 0;line-height:1.8;color:#475569}</style>
